"use strict";(self.webpackChunkdocusaurus=self.webpackChunkdocusaurus||[]).push([["6584"],{63626(e,n,s){s.r(n),s.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>a,metadata:()=>t,toc:()=>h});var t=s(95593),i=s(74848),r=s(28453);let a={title:"Beyond harness engineering",date:"2026-04-16 16:20:00 +1000",slug:"/2026/04/16/beyond-harness-engineering-why-ai-success-is-a-governance-problem",description:"Harness engineering matters, but once AI touches real work and real systems, success becomes a governance problem."},o,l={authorsImageUrls:[]},h=[{value:"Harness engineering is real, and it matters",id:"harness-engineering-is-real-and-it-matters",level:2},{value:"But harness engineering is still local",id:"but-harness-engineering-is-still-local",level:2},{value:"AI success stops being a tooling problem very quickly",id:"ai-success-stops-being-a-tooling-problem-very-quickly",level:2},{value:"Governance is the larger frame",id:"governance-is-the-larger-frame",level:2},{value:"The real problem is coherence",id:"the-real-problem-is-coherence",level:2},{value:"Engineer the harness, govern the system",id:"engineer-the-harness-govern-the-system",level:2},{value:"Beyond the harness",id:"beyond-the-harness",level:2}];function c(e){let n={h2:"h2",li:"li",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.p,{children:"As AI adoption matures, the language around it is getting better."}),"\n",(0,i.jsx)(n.p,{children:"For a while, much of the conversation was trapped in the shallow end: prompts, chatbots, and isolated model tricks. Then came better terms like context engineering, which helped explain that model output depends heavily on what information, memory, tools, and framing surround it."}),"\n",(0,i.jsx)(n.p,{children:"More recently, harness engineering has emerged as a useful practical label. It captures the work of building the wrapper around an AI system: the prompts, tools, tests, retries, scripts, context loaders, verification steps, and operational scaffolding that make an agent more reliable in the real world."}),"\n",(0,i.jsx)(n.p,{children:"That is a good term. It names something real."}),"\n",(0,i.jsx)(n.p,{children:"But it is still not the full picture."}),"\n",(0,i.jsx)(n.p,{children:"Because once AI starts interacting with real work, real systems, real permissions, and real people, the challenge is no longer just harness engineering."}),"\n",(0,i.jsx)(n.p,{children:"It becomes governance."}),"\n",(0,i.jsx)(n.h2,{id:"harness-engineering-is-real-and-it-matters",children:"Harness engineering is real, and it matters"}),"\n",(0,i.jsx)(n.p,{children:"Harness engineering is the discipline of making AI actually usable."}),"\n",(0,i.jsx)(n.p,{children:"It is what happens when you stop treating the model like a magic box and start designing the surrounding system properly. You add better instructions. You expose the right tools. You tighten the feedback loops. You build test paths, validation scripts, memory boundaries, and execution patterns. You learn from mistakes and make them less repeatable."}),"\n",(0,i.jsx)(n.p,{children:"This is good engineering."}),"\n",(0,i.jsx)(n.p,{children:"It is also increasingly necessary. An agent without a harness is mostly hope. An agent with a harness can begin to behave like a working component in a broader system."}),"\n",(0,i.jsx)(n.p,{children:"That is real progress."}),"\n",(0,i.jsx)(n.h2,{id:"but-harness-engineering-is-still-local",children:"But harness engineering is still local"}),"\n",(0,i.jsx)(n.p,{children:"The harness improves execution, but it does not define the whole system the execution belongs to."}),"\n",(0,i.jsx)(n.p,{children:"A harness can help an agent do the right thing more often. It can reduce errors. It can improve consistency. It can make workflows faster and more repeatable."}),"\n",(0,i.jsx)(n.p,{children:"But it does not, by itself, answer bigger questions:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Who decides what the system is trying to optimize?"}),"\n",(0,i.jsx)(n.li,{children:"What sources of context are legitimate?"}),"\n",(0,i.jsx)(n.li,{children:"What permissions should exist, and who should hold them?"}),"\n",(0,i.jsx)(n.li,{children:"What gets remembered, and what should be forgotten?"}),"\n",(0,i.jsx)(n.li,{children:"How are decisions traced, reviewed, challenged, or reversed?"}),"\n",(0,i.jsx)(n.li,{children:"What happens when local optimisation damages the wider system?"}),"\n",(0,i.jsx)(n.li,{children:"How do multiple agents, teams, and workflows remain coherent over time?"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"These are not harness questions."}),"\n",(0,i.jsx)(n.p,{children:"These are governance questions."}),"\n",(0,i.jsx)(n.h2,{id:"ai-success-stops-being-a-tooling-problem-very-quickly",children:"AI success stops being a tooling problem very quickly"}),"\n",(0,i.jsx)(n.p,{children:"The moment AI moves beyond a toy use case, it starts shaping behaviour."}),"\n",(0,i.jsx)(n.p,{children:"Not just model behaviour. Human behaviour. Organisational behaviour. System behaviour."}),"\n",(0,i.jsx)(n.p,{children:"It affects what work gets surfaced and what gets ignored.\nIt affects how knowledge is captured, translated, or lost.\nIt affects who can act, who can approve, and who can see.\nIt affects what becomes normal, what becomes measurable, and what becomes invisible."}),"\n",(0,i.jsx)(n.p,{children:"This is why so many AI initiatives feel strangely incomplete. Teams improve prompts, bolt on tools, add retrieval, add agents, add orchestration, and still fail to get stable value."}),"\n",(0,i.jsx)(n.p,{children:"They assume they are dealing with a technical performance problem when they are actually dealing with a system-shaping problem."}),"\n",(0,i.jsx)(n.p,{children:"The harness is working on the execution path.\nBut the organisation is still under-governed."}),"\n",(0,i.jsx)(n.h2,{id:"governance-is-the-larger-frame",children:"Governance is the larger frame"}),"\n",(0,i.jsx)(n.p,{children:"Governance is often misunderstood as oversight, compliance, or bureaucracy. That is too narrow."}),"\n",(0,i.jsx)(n.p,{children:"Governance is the set of forces, rules, structures, signals, and constraints that shape behaviour in a system."}),"\n",(0,i.jsx)(n.p,{children:"In AI, that means governance is not just the policy document sitting above the stack. It is the wider control plane that determines how the stack behaves at all."}),"\n",(0,i.jsx)(n.p,{children:"Governance shapes:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"what context can enter the system"}),"\n",(0,i.jsx)(n.li,{children:"what tools can be used"}),"\n",(0,i.jsx)(n.li,{children:"what actions are allowed"}),"\n",(0,i.jsx)(n.li,{children:"what evidence is required"}),"\n",(0,i.jsx)(n.li,{children:"what memory persists"}),"\n",(0,i.jsx)(n.li,{children:"what standards must be met"}),"\n",(0,i.jsx)(n.li,{children:"how changes are introduced"}),"\n",(0,i.jsx)(n.li,{children:"how failures are detected"}),"\n",(0,i.jsx)(n.li,{children:"how accountability is maintained"}),"\n",(0,i.jsx)(n.li,{children:"how the system learns over time"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"Seen this way, prompt engineering, context engineering, and harness engineering are not alternatives to governance. They are downstream from it."}),"\n",(0,i.jsx)(n.p,{children:"Governance is the broader pattern that gives them meaning."}),"\n",(0,i.jsx)(n.h2,{id:"the-real-problem-is-coherence",children:"The real problem is coherence"}),"\n",(0,i.jsx)(n.p,{children:"Most failed AI efforts do not fail because the model is too weak."}),"\n",(0,i.jsx)(n.p,{children:"They fail because the surrounding system is incoherent."}),"\n",(0,i.jsx)(n.p,{children:"The AI is told to be helpful, but not given clear authority boundaries.\nIt is connected to tools, but not to trustworthy validation.\nIt is given memory, but not memory discipline.\nIt is asked to move fast, but not told what must never break.\nIt is deployed into teams, but without clear accountability for decisions and outcomes.\nIt is measured on visible activity instead of meaningful contribution."}),"\n",(0,i.jsx)(n.p,{children:"In that environment, better harnesses help, but only up to a point."}),"\n",(0,i.jsx)(n.p,{children:"You can keep improving the wrapper and still get poor organisational results because the issue is not just whether the agent can act. The issue is whether the broader system gives that action coherence, legitimacy, and useful direction."}),"\n",(0,i.jsx)(n.h2,{id:"engineer-the-harness-govern-the-system",children:"Engineer the harness, govern the system"}),"\n",(0,i.jsx)(n.p,{children:"This is the real shift."}),"\n",(0,i.jsx)(n.p,{children:"Harness engineering should absolutely continue. It is practical, valuable, and necessary. We need better wrappers, better tooling, better verification, and better operational patterns."}),"\n",(0,i.jsx)(n.p,{children:"But we should stop pretending that this is the whole problem."}),"\n",(0,i.jsx)(n.p,{children:"If AI is going to succeed in real organisations, then success depends on governance:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"governance of context"}),"\n",(0,i.jsx)(n.li,{children:"governance of permissions"}),"\n",(0,i.jsx)(n.li,{children:"governance of memory"}),"\n",(0,i.jsx)(n.li,{children:"governance of workflow"}),"\n",(0,i.jsx)(n.li,{children:"governance of evidence"}),"\n",(0,i.jsx)(n.li,{children:"governance of change"}),"\n",(0,i.jsx)(n.li,{children:"governance of accountability"}),"\n",(0,i.jsx)(n.li,{children:"governance of organisational learning"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"Harness engineering makes agents more effective."}),"\n",(0,i.jsx)(n.p,{children:"Governance makes AI use coherent."}),"\n",(0,i.jsx)(n.p,{children:"One improves execution quality.\nThe other determines whether the execution belongs in a functioning system at all."}),"\n",(0,i.jsx)(n.h2,{id:"beyond-the-harness",children:"Beyond the harness"}),"\n",(0,i.jsx)(n.p,{children:"So yes, harness engineering is a useful term."}),"\n",(0,i.jsx)(n.p,{children:"It names an important phase in the maturation of AI practice. It reflects a move away from prompt tinkering and toward system design. That is a genuine step forward."}),"\n",(0,i.jsx)(n.p,{children:"But if we stop there, we will keep solving the smaller problem."}),"\n",(0,i.jsx)(n.p,{children:"The bigger problem is not just how to make an agent perform better inside its wrapper."}),"\n",(0,i.jsx)(n.p,{children:"It is how to shape the forces around AI so that behaviour, decisions, knowledge, and action remain aligned across the whole system."}),"\n",(0,i.jsx)(n.p,{children:"That is why AI success is a governance problem."}),"\n",(0,i.jsx)(n.p,{children:"And that is why we need to go beyond harness engineering."})]})}function d(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,n,s){s.d(n,{R:()=>a,x:()=>o});var t=s(96540);let i={},r=t.createContext(i);function a(e){let n=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),t.createElement(r.Provider,{value:n},e.children)}},95593(e){e.exports=JSON.parse('{"permalink":"/blog/2026/04/16/beyond-harness-engineering-why-ai-success-is-a-governance-problem","source":"@site/blog/2026-04-16-beyond-harness-engineering-why-ai-success-is-a-governance-problem.md","title":"Beyond harness engineering","description":"Harness engineering matters, but once AI touches real work and real systems, success becomes a governance problem.","date":"2026-04-16T16:20:00.000Z","tags":[],"readingTime":5.13,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Beyond harness engineering","date":"2026-04-16 16:20:00 +1000","slug":"/2026/04/16/beyond-harness-engineering-why-ai-success-is-a-governance-problem","description":"Harness engineering matters, but once AI touches real work and real systems, success becomes a governance problem."},"unlisted":false,"prevItem":{"title":"What Git did for code, KnowledgeFund will do for organisations","permalink":"/blog/2026/04/16/what-git-did-for-code-knowledgefund-will-do-for-organisations"},"nextItem":{"title":"Same old AI playbook, same old results","permalink":"/blog/2026/04/15/are-you-rolling-out-ai-with-the-same-old-playbook"}}')}}]);